solution.code:
def flatten(nested):
    result = []
    for item in nested:
        if isinstance(item, list):
            result.extend(flatten(item))   # recursive case
        else:
            result.append(item)            # base case: a leaf
    return result

def make_multipliers(n):
    def make(i):
        return lambda x: x * i
    return [make(i) for i in range(n)]

